import type {IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_CURSOR_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  // eslint-disable-next-line re-lint/prefer-polymorphism -- the switch narrows an untrusted frame's claimed type at the trust boundary; a string-keyed lookup loses that (adrs/ADR-006-lint-suppressions.md)
  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// A limit is optional, but one present must be a whole number of rows a store can take.
const isNonNegativeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0;

// The parsed frame carries only what list_sessions defines, so a client-supplied userId reaches the store through no answer.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (limit !== undefined && !isNonNegativeInteger(limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const before = message.before === undefined ? undefined : listSessionsCursor(message.before);
  if (typeof before === 'string') {
    return {valid: false, error: before};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit !== undefined && {limit}),
      ...(before !== undefined && {before}),
    },
  };
}

// A cursor sent back by a client is JSON, so a Date cannot arrive: only a parseable string or an epoch number is one.
function listSessionsCursor(before: unknown): SessionCursor | string {
  if (typeof before !== 'object' || before === null) {
    return 'list_sessions before must be an object';
  }

  const cursor = before as Record<string, unknown>;
  const sessionId = cursor.sessionId;
  if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_CURSOR_SESSION_ID_LENGTH) {
    return `list_sessions before.sessionId must be a string of 1 to ${MAX_CURSOR_SESSION_ID_LENGTH} characters`;
  }

  const updatedAt = cursor.updatedAt;
  // A string reads as its instant, a number is already an epoch; anything else carries no moment at all.
  const timestamp = typeof updatedAt === 'string' ? Date.parse(updatedAt) : updatedAt;
  if (typeof timestamp !== 'number' || !Number.isFinite(timestamp)) {
    return 'list_sessions before.updatedAt must be a timestamp Date.parse accepts';
  }

  return {sessionId, updatedAt: updatedAt as string | number};
}
